/**
 * Wave 8 games — make Nightingale, Squad, Space Engineers, Killing Floor 2,
 * Barotrauma and Insurgency: Sandstorm orderable. Same Docker/OsTemplate
 * pattern as every prior wave: each is a community Docker image (wrapping
 * SteamCMD, +Wine where the dedicated-server build is Windows-only) installed
 * by the OsTemplate.setupScript in cloud-init, clones the golden Ubuntu
 * template (baseVmid 9000), and reuses the generic worker/index.ts
 * wrapDockerGameService() + worker/game-control.ts start/stop/backup
 * machinery (matches on `docker run -d --name <x> ...`) — no new
 * provisioning code needed.
 *
 * Once Human was researched alongside this batch and is DELIBERATELY NOT
 * SEEDED: its "Custom Servers" feature is a rental subscription that runs
 * entirely on NetEase/Starry Studio's own infrastructure, not a downloadable
 * SteamCMD dedicated-server binary — confirmed via official NetEase
 * announcements and PC Gamer coverage. There is no self-hostable option at
 * all, so unlike DayZ (Wave 4, a real credential blocker) or Schedule I
 * (Wave 3/7, P2P/lobby-only) this is a straightforward "nothing to scaffold"
 * case — no lib/games.ts entry, no OsTemplate, no GamePlan.
 *
 * Steam App IDs (dedicated server, NOT the game client) / install method,
 * researched 2026-08-31:
 *   nightingale   3796810  (Nightingale Dedicated Server — confirmed Linux support)
 *   squad         403240   (Squad Dedicated Server — native Linux)
 *   spaceengineers 298740  (Space Engineers Dedicated Server — Windows-only, Wine image)
 *   kf2           232130   (Killing Floor 2 Dedicated Server — native Linux)
 *   barotrauma    N/A here (built-in server tool over SteamCMD — native Linux,
 *                           handled internally by the community image)
 *   sandstorm     581330   (Insurgency: Sandstorm Dedicated Server — native Linux)
 *
 * Docker image notes:
 *   - nightingale: fireblade004/nightingale-server (Ubuntu SteamCMD base,
 *     modeled on wolveix's Satisfactory container pattern already trusted
 *     elsewhere in this catalog). Sanity-checked 2026-08-31: the image and its
 *     GitHub repo (fireblade004/nightingale-server) are live and documented,
 *     but the repo itself only has ~3 commits and no recent activity, and its
 *     own README explicitly says "this container is currently in experimental
 *     state, you may experience issues including complete loss of saved-data."
 *     Seeded anyway per the pre-supplied research call (it's the only
 *     community image for this title and Nightingale itself is a recent
 *     release — same "first mover" position as several already-live Wave 3/4
 *     titles) — but flagged here for a support-side heads-up on backup
 *     cadence, unlike every other family in this file which carries no such
 *     caveat.
 *   - squad: cm2network/squad — same publisher already trusted for tf2
 *     (Wave 4), long-established Source/UE4-adjacent SteamCMD wrapper,
 *     auto-updates the game on container start. Official upstream example
 *     uses `--net=host`; this file uses explicit `-p` mappings instead to
 *     match every other family's convention (host networking would also
 *     collide across multiple game VMs sharing a bridge).
 *   - spaceengineers: mmmaxwwwell/space-engineers-dedicated-docker-linux —
 *     Wine-wrapped (SE has no official Linux server build), the same accepted
 *     precedent already used for icarus/sunkenland/abioticfactor/arkasa/
 *     theforest/sonsoftheforest in Waves 3/4/7.
 *   - kf2: rouhim/killing-floor-2-server — actively maintained (updated within
 *     the last day at research time), automated CI/CD + security audits per
 *     its GitHub repo.
 *   - barotrauma: thijsvanloef/barotrauma-server-docker — the standard,
 *     best-documented community image for this title, fully env-var driven.
 *   - sandstorm: andrewmhub/insurgency-sandstorm — actively maintained
 *     (auto-rebuilds on upstream Steam app updates, updated ~11 days ago at
 *     research time). NOTE: the other well-known option, RouHim/
 *     insurgency-sandstorm-docker, was checked and is ARCHIVED (read-only
 *     since April 2025) — deliberately not used.
 *
 * RCON: all six ship with rcon:"none" in lib/game-control.ts even though
 * squad/kf2 do have a real console underneath — mirrors the precedent from
 * every prior wave of not reverse-engineering a brand-new community image's
 * internal cfg-file layout without a live box to confirm paths against.
 *
 * NOTE: static in-container placeholder passwords ("changeme12"/blank) —
 * customers change them post-deploy, matching every prior wave.
 *
 * Idempotent: OsTemplates upsert by slug; GamePlans dedupe by (gameFamily, name).
 * Run: cd /opt/nxeon-staging && npx tsx prisma/seed-wave8-games.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type Template = { family: string; name: string; setupScript: string; minRamMB: number; minDiskGB: number };

const TEMPLATES: Template[] = [
  {
    family: "nightingale", name: "Nightingale Server", minRamMB: 4096, minDiskGB: 20,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/nightingale/config /opt/nightingale/savedata && docker run -d --name nightingale --hostname nightingale --restart unless-stopped -p 7777:7777/tcp -p 7777:7777/udp -e MAXPLAYERS='4' -e PUID='1000' -e PGID='1000' -e CONNECTIONPASSWORD='changeme12' -v /opt/nightingale/config:/config -v /opt/nightingale/savedata:/config/gamefiles/NWX/Saved fireblade004/nightingale-server:latest`,
  },
  {
    family: "squad", name: "Squad Server", minRamMB: 16384, minDiskGB: 40,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/squad && docker run -d --name squad --restart unless-stopped -p 7787:7787/udp -p 27165:27165/udp -p 15000:15000/udp -p 21114:21114/tcp -e SERVER_NAME='Nxeon Squad' -e PORT='7787' -e QUERYPORT='27165' -e BEACONPORT='15000' -e RCONPORT='21114' -e FIXEDMAXPLAYERS='50' -v /opt/squad:/home/steam/squad-dedicated cm2network/squad:latest`,
  },
  {
    family: "spaceengineers", name: "Space Engineers Server", minRamMB: 8192, minDiskGB: 30,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/spaceengineers/World /opt/spaceengineers/SpaceEngineersDedicated /opt/spaceengineers/steamcmd && docker run -d --name spaceengineers --restart unless-stopped -p 27016:27016/udp -v /opt/spaceengineers/World:/appdata/space-engineers/World -v /opt/spaceengineers/SpaceEngineersDedicated:/appdata/space-engineers/SpaceEngineersDedicated -v /opt/spaceengineers/steamcmd:/home/se/.steam mmmaxwwwell/space-engineers-dedicated-docker-linux:latest`,
  },
