  { gameFamily: "nightingale", name: "Nightingale — 6 GB / 6 players", ramMB: 6144, cpuCores: 2, diskGB: 25, slots: 6, priceCents: 1299, featured: true },
  { gameFamily: "nightingale", name: "Nightingale — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 30, slots: 8, priceCents: 1699 },

  // Squad — large-scale 100-player tactical FPS; official recs call for 16GB+ RAM,
  // meaningfully heavier than the rest of the catalog, priced/sized accordingly.
  { gameFamily: "squad", name: "Squad — 16 GB / 50 players", ramMB: 16384, cpuCores: 6, diskGB: 40, slots: 50, priceCents: 2999 },
  { gameFamily: "squad", name: "Squad — 24 GB / 80 players", ramMB: 24576, cpuCores: 8, diskGB: 60, slots: 80, priceCents: 4499, featured: true },
  { gameFamily: "squad", name: "Squad — 32 GB / 100 players", ramMB: 32768, cpuCores: 10, diskGB: 80, slots: 100, priceCents: 5999 },

  // Space Engineers — Wine-based sim, similar weight to Icarus/Enshrouded.
  { gameFamily: "spaceengineers", name: "Space Engineers — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 30, slots: 8, priceCents: 1399 },
  { gameFamily: "spaceengineers", name: "Space Engineers — 12 GB / 16 players", ramMB: 12288, cpuCores: 4, diskGB: 40, slots: 16, priceCents: 1999, featured: true },
  { gameFamily: "spaceengineers", name: "Space Engineers — 16 GB / 32 players", ramMB: 16384, cpuCores: 6, diskGB: 60, slots: 32, priceCents: 2799 },

  // Killing Floor 2 — classic UE3 co-op shooter, similar scale/pricing to TF2/L4D2 (Wave 4).
  { gameFamily: "kf2", name: "Killing Floor 2 — 2 GB / 6 players", ramMB: 2048, cpuCores: 2, diskGB: 20, slots: 6, priceCents: 599 },
  { gameFamily: "kf2", name: "Killing Floor 2 — 4 GB / 12 players", ramMB: 4096, cpuCores: 3, diskGB: 30, slots: 12, priceCents: 999, featured: true },
  { gameFamily: "kf2", name: "Killing Floor 2 — 6 GB / 24 players", ramMB: 6144, cpuCores: 3, diskGB: 40, slots: 24, priceCents: 1399 },

  // Barotrauma — lightweight co-op sub sim, similar scale/pricing to DST/Core Keeper.
  { gameFamily: "barotrauma", name: "Barotrauma — 2 GB / 8 players", ramMB: 2048, cpuCores: 1, diskGB: 10, slots: 8, priceCents: 499 },
  { gameFamily: "barotrauma", name: "Barotrauma — 3 GB / 12 players", ramMB: 3072, cpuCores: 2, diskGB: 15, slots: 12, priceCents: 799, featured: true },
  { gameFamily: "barotrauma", name: "Barotrauma — 4 GB / 16 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 16, priceCents: 1099 },

  // Insurgency: Sandstorm — tactical UE4 shooter, similar scale/pricing to TF2/L4D2 with a
  // slightly heavier footprint.
  { gameFamily: "sandstorm", name: "Insurgency: Sandstorm — 3 GB / 16 players", ramMB: 3072, cpuCores: 2, diskGB: 25, slots: 16, priceCents: 799 },
  { gameFamily: "sandstorm", name: "Insurgency: Sandstorm — 4 GB / 24 players", ramMB: 4096, cpuCores: 3, diskGB: 35, slots: 24, priceCents: 1199, featured: true },
  { gameFamily: "sandstorm", name: "Insurgency: Sandstorm — 6 GB / 32 players", ramMB: 6144, cpuCores: 3, diskGB: 45, slots: 32, priceCents: 1599 },
];

async function main() {
  const templateIdByFamily = new Map<string, string>();
  let sort = 100;
  for (const t of TEMPLATES) {
    const os = await db.osTemplate.upsert({
      where: { slug: t.family },
      create: {
        slug: t.family, name: t.name, category: "APPLICATION", family: t.family, version: "", logo: t.family,
        vmid: 9000, baseVmid: 9000, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB,
        licenseRequired: false, featured: false, sortOrder: sort++, active: true,
      },
      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
    });
    templateIdByFamily.set(t.family, os.id);
    console.log(`  osTemplate ${t.family.padEnd(16)} → ${os.id}`);
  }

  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
  const largest = plans[plans.length - 1];

  let created = 0, updated = 0;
  const sortByGame = new Map<string, number>();
  for (const spec of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
    sortByGame.set(spec.gameFamily, sortOrder + 1);
    const data = {
      gameFamily: spec.gameFamily, name: spec.name, ramMB: spec.ramMB, cpuCores: spec.cpuCores, diskGB: spec.diskGB,
      slots: spec.slots, priceCents: spec.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: osId,
      featured: spec.featured ?? false, active: true, sortOrder,
    };
    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
    if (existing) { await db.gamePlan.update({ where: { id: existing.id }, data }); updated++; }
    else { await db.gamePlan.create({ data }); created++; }
    console.log(`  plan ${spec.name.padEnd(42)} base=${basePlan.name}`);
  }
  console.log(`\nWave 8: ${TEMPLATES.length} OsTemplates, GamePlans ${created} created / ${updated} updated.`);
  console.log(`Once Human NOT seeded — no self-hostable dedicated server exists, see file header comment.`);
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());

